// RemoteOK API: array where index 0 is metadata, rest are jobs
const jobs = [];
const raw = $input.first().json;
const list = Array.isArray(raw) ? raw : [];

for (let i = 1; i < list.length; i++) {
  const job = list[i];
  if (!job || !job.position) continue;

  let salary = '';
  if (job.salary_min && job.salary_max) {
    salary = `USD ${Number(job.salary_min).toLocaleString()} - ${Number(job.salary_max).toLocaleString()}/yr`;
  } else if (job.salary_min) {
    salary = `From USD ${Number(job.salary_min).toLocaleString()}/yr`;
  }

  const tags = Array.isArray(job.tags) ? job.tags : [];
  const desc = `${(job.description || '').replace(/<[^>]*>/g, ' ')} ${tags.join(' ')}`.replace(/\s+/g, ' ').trim();

  jobs.push({
    job_id: `remoteok_${job.slug || job.id || i}`,
    job_title: job.position || '',
    company: job.company || '',
    job_url: job.url || `https://remoteok.com/remote-jobs/${job.slug}`,
    source: 'RemoteOK',
    location_text: job.location || 'Worldwide',
    salary,
    description: desc,
    posted_date: job.date || new Date().toISOString(),
    tags: tags.join(', '),
    date_found: new Date().toISOString()
  });
}

return jobs.map(j => ({ json: j }));

