const jobs = [];

for (const item of $input.all()) {
  const data = item.json;
  const rawTitle = data.title || '';
  const url = data.link || data.guid || '';

  // WWR format: "Category: Company: Job Title" — take last two parts
  let company = '';
  let jobTitle = rawTitle;
  const parts = rawTitle.split(': ');
  if (parts.length >= 2) {
    company = parts[parts.length - 2].trim();
    jobTitle = parts[parts.length - 1].trim();
  }

  const rawDesc = data.content || data.contentSnippet || data.description || '';
  const desc = rawDesc.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  const cats = Array.isArray(data.categories) ? data.categories : (data.categories ? [data.categories] : []);
  const urlB64 = Buffer.from(url).toString('base64').slice(0, 24);

  jobs.push({
    job_id: `wwr_${urlB64}`,
    job_title: jobTitle,
    company,
    job_url: url,
    source: 'We Work Remotely',
    location_text: 'Worldwide',
    salary: '',
    description: desc,
    posted_date: data.pubDate || data.isoDate || new Date().toISOString(),
    tags: cats.join(', '),
    date_found: new Date().toISOString()
  });
}

return jobs.map(j => ({ json: j }));

