// YC Work at a Startup — JSON structure varies; handle both array and nested
const jobs = [];
const raw = $input.first().json;
const list = Array.isArray(raw) ? raw : (raw.jobs || raw.results || []);

for (const job of list) {
  const url = job.url || job.href || `https://www.workatastartup.com/jobs/${job.id || ''}`;
  const urlB64 = Buffer.from(url).toString('base64').slice(0, 24);
  const desc = (job.description || job.body || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

  jobs.push({
    job_id: `yc_${job.id || urlB64}`,
    job_title: job.title || job.role || '',
    company: (job.company && (job.company.name || job.company)) || '',
    job_url: url,
    source: 'YC Work at a Startup',
    location_text: job.location || 'Worldwide',
    salary: job.salary || job.compensation || '',
    description: desc,
    posted_date: job.created_at || new Date().toISOString(),
    tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
    date_found: new Date().toISOString()
  });
}

return jobs.map(j => ({ json: j }));

// $input.all() = existing jobs from Google Sheets (Read Existing Jobs node)
// $('Merge All Sources').all() = freshly fetched new jobs
const existingItems = $input.all();
const newJobs = $('Merge All Sources').all();

const existingUrls = new Set(existingItems.map(i => (i.json.job_url || '').toLowerCase()).filter(Boolean));
const existingKeys = new Set(
  existingItems.map(i => `${(i.json.company || '').toLowerCase()}|||${(i.json.job_title || '').toLowerCase()}`).filter(k => k !== '|||')
);

const seen = new Set();
const dedupedJobs = [];

for (const item of newJobs) {
  const job = item.json;
  const urlKey = (job.job_url || '').toLowerCase();
  const compKey = `${(job.company || '').toLowerCase()}|||${(job.job_title || '').toLowerCase()}`;

  if (existingUrls.has(urlKey)) continue;
  if (existingKeys.has(compKey)) continue;
  if (seen.has(urlKey)) continue;

  seen.add(urlKey);
  dedupedJobs.push(item);
}

return dedupedJobs;

const REJECT = [
  /\bus[\s-]?only\b/i,
  /\bunited[\s-]?states[\s-]?only\b/i,
  /\busa[\s-]?only\b/i,
  /\bcanada[\s-]?only\b/i,
  /\buk[\s-]?only\b/i,
  /\bunited[\s-]?kingdom[\s-]?only\b/i,
  /\beu[\s-]?only\b/i,
  /\beurope[\s-]?only\b/i,
  /\baustralia[\s-]?only\b/i,
  /\bnew[\s-]?zealand[\s-]?only\b/i,
  /\bmust be based in\b/i,
  /\bmust live in\b/i,
  /\bmust reside in\b/i,
  /\bmust be authorized to work in\b/i,
  /\bauthorized to work in (the )?(us|uk|eu|canada|australia)\b/i,
  /\blocal work permit required\b/i,
  /\bwork permit required\b/i,
  /\bhybrid\b/i,
  /\bon[\s-]?site\b/i,
  /\boffice required\b/i,
  /\bin[\s-]?office\b/i,
  /\bremote within (the )?(us|uk|eu|canada|australia|europe)\b/i,
  /\bonly (applicants|candidates) (in|from) (the )?(us|uk|eu|europe|canada|australia)\b/i,
  /\bno (visa|sponsorship)\b.*?(outside|non).*?(us|uk|eu)/i,
  /\bfixed (us|est|pst|cet|gmt) hours\b/i,
  /\bwork authorization required in (the )?(us|uk|eu|canada|australia)\b/i,
  /\brelocate\b/i
];

const filtered = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.location_text || ''} ${job.description || ''} ${job.title || ''}`;

  let rejected = false;
  let rejectReason = '';
  for (const re of REJECT) {
    if (re.test(text)) {
      rejected = true;
      rejectReason = re.toString();
      break;
    }
  }

  if (!rejected) {
    filtered.push(item);
  }
}

return filtered;

// Merge AI response into job data
const job = $('Taiwan Hard Filter').item.json;
const aiRaw = $input.item.json;

let aiResult = {
  taiwan_eligible: 'unclear',
  reason: 'Parse error',
  location_risk: 'medium',
  timezone_risk: 'medium',
  contractor_possible: 'unclear',
  decision: 'manual_check'
};

try {
  const content = aiRaw?.content?.[0]?.text || aiRaw?.choices?.[0]?.message?.content || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiResult = { ...aiResult, ...JSON.parse(jsonMatch[0]) };
  }
} catch (e) {
  aiResult.reason = `Parse error: ${e.message}`;
}

// Reject immediately if AI says no
if (aiResult.decision === 'reject' || aiResult.location_risk === 'high') {
  return null; // Drop this item
}

return {
  json: {
    ...job,
    taiwan_eligible: aiResult.taiwan_eligible,
    taiwan_reason: aiResult.reason,
    location_risk: aiResult.location_risk,
    timezone_risk: aiResult.timezone_risk,
    contractor_possible: aiResult.contractor_possible,
    ai_decision: aiResult.decision
  }
};

const ASYNC_POSITIVE = [
  /\basync\b/i,
  /\basynchronous\b/i,
  /\bflexible hours\b/i,
  /\bflexible schedule\b/i,
  /\bdistributed team\b/i,
  /\bremote[\s-]?first\b/i,
  /\blow[\s-]?meeting\b/i,
  /\bwork across time.?zones?\b/i,
  /\btime.?zone flexible\b/i,
  /\bno fixed hours\b/i,
  /\byour own schedule\b/i,
  /\bset your own hours\b/i
];

const ASYNC_NEGATIVE = [
  /\bstrict 9.?to.?5\b/i,
  /\bfixed (us|est|pst|cet|gmt)[\s-]?hours\b/i,
  /\bdaily live calls? required\b/i,
  /\bmust overlap (full|entire) business day\b/i,
  /\bcore hours.{0,30}(est|pst|cet|gmt)\b/i,
  /\b(9am|9:00)[\s-]?(to|-)?.?(5pm|17:00)[\s-]?(est|pst|cet)\b/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.description || ''} ${job.tags || ''} ${job.job_title || ''}`;

  let hasNegative = false;
  for (const re of ASYNC_NEGATIVE) {
    if (re.test(text)) { hasNegative = true; break; }
  }
  if (hasNegative) continue;

  let positiveCount = 0;
  for (const re of ASYNC_POSITIVE) {
    if (re.test(text)) positiveCount++;
  }

  let async_level = 'low';
  if (positiveCount >= 2) async_level = 'high';
  else if (positiveCount === 1) async_level = 'medium';

  results.push({ json: { ...job, async_level } });
}

return results;

const PRIMARY_ROLES = [
  /\bdata analyst\b/i,
  /\bdata scientist\b/i,
  /\bjunior data scientist\b/i,
  /\bbusiness intelligence\b/i,
  /\bBI analyst\b/i,
  /\bmarketing analyst\b/i,
  /\bperformance marketing\b/i,
  /\bgrowth analyst\b/i,
  /\bai marketing\b/i,
  /\bai automation\b/i,
  /\bai workflow\b/i,
  /\bmartech\b/i,
  /\bcreative strategist\b/i,
  /\bmarketing data\b/i,
  /\banalytics engineer\b/i
];

const ADJACENT_ROLES = [
  /\bmarketing\b/i,
  /\banalytics\b/i,
  /\bautomation\b/i,
  /\bgrowth\b/i,
  /\bseo\b/i,
  /\bppc\b/i,
  /\bdigital marketing\b/i,
  /\bcontent\b/i,
  /\breporting\b/i,
  /\bdashboard\b/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title || ''} ${job.description || ''} ${job.tags || ''}`;
  const whyFit = [];
  let score = 0;

  // ── Taiwan eligibility (40 pts max) ────────────────
  const eli = job.taiwan_eligible || 'unclear';
  const locRisk = job.location_risk || 'medium';
  if (eli === 'yes' && locRisk === 'low') {
    score += 40; whyFit.push('Clearly worldwide/global eligible');
  } else if (eli === 'yes' || /apac/i.test(job.location_text || '')) {
    score += 30; whyFit.push('APAC or broadly remote eligible');
  } else if (eli === 'unclear' && locRisk !== 'high') {
    score += 20; whyFit.push('No hard country restriction found');
  }

  // ── Async fit (25 pts max) ─────────────────────────
  const asyncLvl = job.async_level || 'low';
  if (asyncLvl === 'high') {
    score += 25; whyFit.push('Clearly async & flexible');
  } else if (asyncLvl === 'medium') {
    score += 20; whyFit.push('Flexible hours mentioned');
  } else {
    score += 10;
  }

  // ── Role fit (25 pts max) ──────────────────────────
  let roleCategory = 'other';
  const isPrimary = PRIMARY_ROLES.some(re => re.test(text));
  const isAdjacent = !isPrimary && ADJACENT_ROLES.some(re => re.test(text));
  if (isPrimary) {
    score += 25; roleCategory = 'primary';
    whyFit.push('Matches data/AI marketing/BI core skills');
  } else if (isAdjacent) {
    score += 15; roleCategory = 'adjacent';
    whyFit.push('Adjacent to marketing/data skills');
  }

  // ── Salary fit (25 pts max) ────────────────────────
  const salaryText = job.salary || '';
  const nums = (salaryText.match(/[\d,]+/g) || []).map(n => parseInt(n.replace(/,/g, '')));
  const maxSal = nums.length ? Math.max(...nums) : 0;
  if (maxSal >= 60000) {
    // Annual salary >= 60k USD = 5k/mo
    score += 25; whyFit.push('Excellent salary (≥ $5k/mo equivalent)');
  } else if (maxSal >= 5000 && maxSal < 60000) {
    // Could be monthly 5k+
    score += 25; whyFit.push('Salary ≥ $5,000/mo');
  } else if (maxSal >= 3000) {
    score += 15; whyFit.push('Salary ≥ $3,000/mo');
  } else if (maxSal > 0) {
    score += 10; whyFit.push('Salary listed');
  }

  // ── Final decision ─────────────────────────────────
  let decision = 'reject';
  if (eli === 'yes' && score >= 85 && asyncLvl !== 'low' && locRisk === 'low') {
    decision = 'apply';
  } else if (score >= 85 && locRisk !== 'high') {
    decision = 'manual_check';
  } else if (eli === 'no' || locRisk === 'high') {
    decision = 'reject';
  } else if (score >= 70) {
    decision = 'keep';
  }

  results.push({
    json: {
      ...job,
      score,
      role_category: roleCategory,
      why_good_fit: whyFit.join('; '),
      decision,
      application_status: 'new',
      notes: ''
    }
  });
}

return results;

const job = $('IF Score 85+').item.json;
const aiRaw = $input.item.json;
const coverText = aiRaw?.content?.[0]?.text || '';

return {
  json: {
    ...job,
    cover_letter_draft: coverText
  }
};

const items = $input.all();
const today = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', month: 'long', day: 'numeric', year: 'numeric' });

// Sort by score descending
const sorted = [...items].sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

const topJobs = sorted.filter(i => i.json.score >= 70).slice(0, 10);
const manualCheck = sorted.filter(i => i.json.ai_decision === 'manual_check' && i.json.score >= 75);
const instantApply = sorted.filter(i => i.json.decision === 'apply');

const rejectStats = {
  usOnly: 0, euOnly: 0, hybrid: 0, tzRisk: 0, lowScore: 0
};
for (const item of items) {
  const j = item.json;
  if ((j.taiwan_reason || '').toLowerCase().includes('us')) rejectStats.usOnly++;
  if ((j.taiwan_reason || '').toLowerCase().includes('eu') || (j.taiwan_reason || '').toLowerCase().includes('europe')) rejectStats.euOnly++;
  if ((j.taiwan_reason || '').toLowerCase().includes('hybrid')) rejectStats.hybrid++;
  if (j.timezone_risk === 'high') rejectStats.tzRisk++;
}

// Build HTML email
let html = `
<html><body style="font-family: Arial, sans-serif; max-width: 700px; margin: auto; color: #222;">
<h1 style="color: #1a56db;">🇹🇼 Daily Taiwan Eligible Async Remote Jobs</h1>
<p style="color: #666;">${today} · Taiwan timezone (Asia/Taipei)</p>
`;

if (instantApply.length > 0) {
  html += `<div style="background:#e8f5e9;padding:12px;border-radius:6px;margin-bottom:20px;">`;
  html += `<strong>⚡ ${instantApply.length} job(s) ready to apply now (score ≥ 85, Taiwan eligible)</strong></div>`;
}

html += `<h2>Top Jobs Today</h2>`;

if (topJobs.length === 0) {
  html += `<p>No jobs passed all filters today. Check the Rejected sheet for details.</p>`;
} else {
  topJobs.forEach((item, idx) => {
    const j = item.json;
    const badge = j.score >= 85 ? '🟢' : j.score >= 75 ? '🟡' : '🟠';
    html += `
    <div style="border:1px solid #ddd;border-radius:8px;padding:16px;margin-bottom:16px;">
      <h3 style="margin:0 0 4px 0;">${badge} ${idx + 1}. ${j.job_title}</h3>
      <p style="margin:0 0 8px 0;color:#555;"><strong>Company:</strong> ${j.company}</p>
      <table style="font-size:14px;width:100%;">
        <tr><td><strong>Score:</strong></td><td>${j.score}/100</td><td><strong>Taiwan eligible:</strong></td><td>${j.taiwan_eligible}</td></tr>
        <tr><td><strong>Async level:</strong></td><td>${j.async_level}</td><td><strong>Timezone risk:</strong></td><td>${j.timezone_risk}</td></tr>
        <tr><td><strong>Location risk:</strong></td><td>${j.location_risk}</td><td><strong>Contractor:</strong></td><td>${j.contractor_possible}</td></tr>
        <tr><td><strong>Salary:</strong></td><td colspan="3">${j.salary || 'Not listed'}</td></tr>
      </table>
      <p style="margin:8px 0 4px 0;"><strong>Reason:</strong> ${j.taiwan_reason}</p>
      <p style="margin:4px 0;"><strong>Why it fits Jerry:</strong> ${j.why_good_fit}</p>
      ${j.cover_letter_draft ? `<details style="margin-top:8px;"><summary style="cursor:pointer;color:#1a56db;">📝 Cover Letter Draft</summary><p style="white-space:pre-wrap;margin-top:8px;padding:12px;background:#f9f9f9;border-radius:4px;">${j.cover_letter_draft}</p></details>` : ''}
      <a href="${j.job_url}" style="display:inline-block;margin-top:10px;padding:8px 14px;background:#1a56db;color:white;text-decoration:none;border-radius:4px;">Apply →</a>
    </div>`;
  });
}

if (manualCheck.length > 0) {
  html += `<h2>🔍 Manual Check Needed</h2>`;
  html += `<p style="color:#666;">High-scoring jobs where Taiwan eligibility is unclear — review before applying.</p>`;
  manualCheck.forEach(item => {
    const j = item.json;
    html += `<div style="border:1px solid #f0ad4e;border-radius:6px;padding:12px;margin-bottom:10px;">
      <strong>${j.job_title}</strong> at ${j.company} · Score: ${j.score} · <a href="${j.job_url}">View job</a><br>
      <small>${j.taiwan_reason}</small>
    </div>`;
  });
}

html += `
<h2>📊 Rejected Summary</h2>
<ul>
  <li>US-only restrictions: <strong>${rejectStats.usOnly}</strong></li>
  <li>EU-only restrictions: <strong>${rejectStats.euOnly}</strong></li>
  <li>Hybrid/onsite: <strong>${rejectStats.hybrid}</strong></li>
  <li>High timezone risk: <strong>${rejectStats.tzRisk}</strong></li>
</ul>
<hr style="margin:24px 0;">
<p style="color:#999;font-size:12px;">Generated by Daily Taiwan Eligible Async Remote Job Hunter · n8n workflow</p>
</body></html>`;

return [{ json: { digest: html, total_filtered: topJobs.length, instant_apply: instantApply.length } }];
